#include "domain/native_archipelago.hpp"
#include "domain/water_locomotion.hpp"
#include "domain/body_terrain_support.hpp"
#include "domain/locomotion_pace.hpp"
#include "domain/environmental_exposure.hpp"
#include <iostream>
using namespace stalthos;
void check(bool b,const char* m){if(!b)throw std::runtime_error(m);}
int main(){try{world::NativeArchipelago native(42);world::ConnectedRoute old(42);
 for(double x:{-80.,0.,80.,136.,220.,280.})for(double z:{-80.,0.,27.,80.})check(native.height(x,z)==old.height(x,z),"origin route and habitats exact");
 check(native.landRegion(0,0,native.triangleHeight(0,0))==1001,"reference creek remains Main Island not ocean");
 for(const auto& r:native.field().regions()){const auto x=r.id==1001?24:r.centerX*.1,z=r.id==1001?24:r.centerZ*.1;check(native.height(x,z)>0,"all four actual shared-field uplands");check(native.landRegion(x,z,native.triangleHeight(x,z))==r.id,"land body identity");}
 auto path=native.firstCrossing();check(bool(path)&&path->seaMeters>20,"real shore-water-land interval");check(native.landRegion(path->start.x,path->start.z,path->start.y)==1001&&native.landRegion(path->end.x,path->end.z,path->end.y)==1003,"Main start actual Stone end");
 int unsupported=0;double maximumDrySlope=0;bool sea=false;for(double d=0;d<path->distance;d+=.5){const auto x=path->start.x+std::sin(path->yaw)*d,z=path->start.z+std::cos(path->yaw)*d,bed=native.triangleHeight(x,z);if(bed>=-.55){auto support=domain::calculateTerrainSupport(x,z,path->yaw,.225,.1125,[&](double gx,double gz){return native.triangleHeight(gx,gz);});maximumDrySlope=std::max(maximumDrySlope,support.slopeAngleRadians);if(!support.supported)++unsupported;}if(bed<-.55){sea=true;check(native.landRegion(x,z,bed)==0,"sea never grants distant island arrival");const auto water=domain::waterMotion(bed,true,0);check(water.mode==domain::WaterMode::Swimming&&water.bodyDatum==-.55,"actual buoyant datum above seabed");}}
 std::cout<<"STANCE unsupported="<<unsupported<<" maximumDrySlope="<<maximumDrySlope<<"\n";check(unsupported==0,"actual dry/wading route supported at same20deg cap");check(sea,"actual deepwater crossed");auto prior=domain::waterMotion(.1,true,0).bodyDatum;for(double bed=.09;bed>=-1;bed-=.01){const auto sample=domain::waterMotion(bed,true,0);check(std::abs(sample.bodyDatum-prior)<.011,"continuous shore wade swim datum");prior=sample.bodyDatum;}
 needs::NeedsCore needs(HeroSpecies::Smalltrotter);needs.restoreState(0,0,.2,0,true);auto water=domain::waterMotion(-5,true,.2);domain::applySwimming(needs,water,10,true);check(!needs.isResting()&&needs.fatigue()>.2,"swim cannot rest-recover fatigue");needs.advance({10,10});check(needs.fatigue()>.2,"one ordinary needs tick retains swim consequence");
 check(domain::waterMotion(-.4,false,0).mode==domain::WaterMode::Land,"protected freshwater not global marine swimming");check(std::isfinite(native.sample(1536,0).position.y),"streamed tile/normal margin beyond playable bounds");world::NativeArchipelago smaller(42,{.05,.1});check(smaller.bounds()==700,"bounds follow accepted draft scale");
 needs::NeedsCore ordinary(HeroSpecies::Smalltrotter);environment::BodyWeatherResponse weather;SimCore clock;double travelled=0;const double pinned=domain::LocomotionPace::calculate(.16128,2,domain::LocomotionPace::Intent::Forward).signedSpeed;int dryFailures=0,wadeFailures=0;
 while(clock.physicalSeconds()<280 && travelled<path->distance-1.5){const double dt=.01;clock.advance(dt,1);const double x=path->start.x+std::sin(path->yaw)*travelled,z=path->start.z+std::cos(path->yaw)*travelled;auto state=domain::waterMotion(native.triangleHeight(x,z),true,ordinary.fatigue());const double speed=state.mode==domain::WaterMode::Swimming?2.2*state.speedFactor:pinned*state.speedFactor;if(clock.physicalSeconds()>=2)travelled+=speed*dt;const double px=path->start.x+std::sin(path->yaw)*travelled,pz=path->start.z+std::cos(path->yaw)*travelled;state=domain::waterMotion(native.triangleHeight(px,pz),true,ordinary.fatigue());const auto conditions=environment::sample(42,1001,clock.calendarSeconds(),{0,0,.35,0});const auto local=weather.advance(conditions,dt,environment::routeWindShelter(px,pz));domain::applySwimming(ordinary,state,dt,true);ordinary.advance({dt,dt});environment::applyExposure(ordinary,local,dt,true);if(state.mode!=domain::WaterMode::Swimming){auto ground=domain::calculateTerrainSupport(px,pz,path->yaw,.225,.1125,[&](double gx,double gz){return native.triangleHeight(gx,gz);});if(!ground.supported){if(state.mode==domain::WaterMode::Wading)++wadeFailures;else ++dryFailures;}}}
 check(travelled>=path->distance-1.5,"actual pinned pace plus ordinary needs/exposure completes bounded crossing");check(dryFailures==0&&wadeFailures==0,"no genuine dry/wade support failures during full-owner traversal");std::cout<<"FULL_OWNER_CROSSING_SECONDS="<<clock.physicalSeconds()<<" fatigue="<<ordinary.fatigue()<<" dry_failures="<<dryFailures<<" wade_failures="<<wadeFailures<<"\n";
 std::cout<<"NATIVE_ARCHIPELAGO_OK shared4/origin preservation/real sea path/land identity/continuous buoyancy/fatigue; crossing meters="<<path->distance<<" sea="<<path->seaMeters<<'\n';return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
